export const makeXml = (): Buffer => {
  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<cfdi:Comprobante xmlns:cfdi="http://www.sat.gob.mx/cfd/4" Version="4.0" Folio="ABC123" Fecha="2026-04-22T10:00:00" Total="1180.00" SubTotal="1000.00">
  <cfdi:Emisor Rfc="ATI100123ABC" Nombre="Acero Tijuana SA"/>
  <cfdi:Receptor Rfc="MAR020220XX1" Nombre="Martinrea Saltillo"/>
</cfdi:Comprobante>
`;
  return Buffer.from(xml, 'utf8');
};
